statement:
Decide whether `password` is strong. It is strong only when every one of these rules holds:

- its length is 8 or more;
- it has a lowercase letter, an uppercase letter and a digit (at least one of each);
- it has at least one special character, where the special characters are exactly `!@#$%^&*()-+`;
- no two neighbouring characters are the same (`"xyx"` is fine, `"xxy"` is not).

Return `true` if the password is strong and `false` if it breaks any rule.

validator:
function validate([password]) {
  if (typeof password !== 'string' || password.length < 1 || password.length > 100) return 'password has 1 to 100 characters.';
  if (!/^[A-Za-z0-9!@#$%^&*()+\-]+$/.test(password)) return 'Only letters, digits and !@#$%^&*()-+ are allowed.';
  return null;
}

reference:
function strongPasswordCheckerII(password) {
  if (password.length < 8) {
    return false;
  }
  const special = "!@#$%^&*()-+";
  let hasLower = false;
  let hasUpper = false;
  let hasDigit = false;
  let hasSpecial = false;

  for (let i = 0; i < password.length; i++) {
    const ch = password[i];
    if (i > 0 && ch === password[i - 1]) {
      return false;
    }
    if (ch >= 'a' && ch <= 'z') {
      hasLower = true;
    } else if (ch >= 'A' && ch <= 'Z') {
      hasUpper = true;
    } else if (ch >= '0' && ch <= '9') {
      hasDigit = true;
    } else if (special.includes(ch)) {
      hasSpecial = true;
    }
  }
  return hasLower && hasUpper && hasDigit && hasSpecial;
}

