function generate(rand, size) {
  const groups = ['abcdefghijklmnopqrstuvwxyz', 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', '0123456789', '!@#$%^&*()-+'];
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 14);
  // Usually every kind of character is allowed; sometimes one kind is left out.
  const allowed = groups.filter(() => rand() < 0.85);
  if (!allowed.length) allowed.push(groups[0]);
  const chars = Array.from({ length: n }, () => pick(pick(allowed)));
  // Place one character of each allowed kind at distinct random positions.
  const spots = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [spots[i], spots[j]] = [spots[j], spots[i]]; }
  allowed.forEach((group, k) => { if (k < n) chars[spots[k]] = pick(group); });
  // Most of the time remove equal neighbours, keeping each character's kind.
  if (rand() < 0.8) {
    for (let i = 1; i < n; i++) {
      const group = groups.find(g => g.includes(chars[i]));
      while (chars[i] === chars[i - 1]) chars[i] = pick(group);
    }
  }
  return [chars.join('')];
}
